package game.agent.growth;
import game.agent.llm.Json;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class GrowthArrivalRecoveryTest{
 @Test void allNavigationModesHealAtCampAndPreserveExperience(){for(String region:Arrays.asList("river","mountain")){GrowthWorld w=new GrowthWorld(()->0);w.starter("TREECKO");for(int i=0;i<160&&!w.region().equals(region);i++)w.execute("go_to_region",Json.object("regionId",region));w.partner().hurt(w.partner().maxHp());w.partner().pp.put("POUND",0);w.partner().status="POISON";int xp=w.partner().experience;for(int i=0;i<160&&!w.canRest();i++)w.execute("go_to_recovery",Collections.emptyMap());assertTrue(w.canRest());assertEquals(w.partner().maxHp(),w.partner().getHitPoints());assertEquals("NONE",w.partner().status);assertEquals(35,w.partner().pp.get("POUND"));assertEquals(xp,w.partner().experience);GrowthWorld.restore(w.export(),()->0);}}
 @Test void campsAreSeparateFromEveryExit(){for(String id:Arrays.asList("river","mountain")){Map<String,Object>m=GrowthMaps.definition(id),r=Json.asObject(m.get("recovery"));for(Object row:Json.asArray(m.get("exits"))){Map<String,Object>e=Json.asObject(row);assertTrue(Math.abs(GrowthPokemon.num(r.get("x"))-GrowthPokemon.num(e.get("x")))+Math.abs(GrowthPokemon.num(r.get("y"))-GrowthPokemon.num(e.get("y")))>=6);}}}
 @Test void manualMovementOntoCampHealsWholeParty()throws Exception{GrowthWorld w=GrowthRespawnTest.cleared();for(int i=0;i<160&&!w.region().equals("river");i++)w.execute("go_to_region",Json.object("regionId","river"));Map<String,Object> seed=w.export();seed.put("x",5);seed.put("y",3);w=GrowthWorld.restore(seed,()->0);java.lang.reflect.Field field=GrowthWorld.class.getDeclaredField("team");field.setAccessible(true);Collection<GrowthPokemon> party=((Map<String,GrowthPokemon>)field.get(w)).values();for(GrowthPokemon p:party){p.hurt(p.maxHp());p.burned=true;for(String move:p.pp.keySet())p.pp.put(move,0);}w.move("N");assertTrue(w.canRest());for(GrowthPokemon p:party){assertEquals(p.maxHp(),p.getHitPoints());assertFalse(p.burned);assertEquals("NONE",p.status);for(String move:p.pp.keySet())assertEquals(GrowthRules.move(move).pp,p.pp.get(move));}GrowthWorld.restore(w.export(),()->0);}
}
